386	// Report the interactive region (physical px) for Windows click-through: the
387	// union of the SPRITE's true bounds and the visible bubble, not the whole
388	// canvas, so the empty space beside the pet passes clicks to apps below.
389	// Every pet window (main, project, extra) registers under its own label so
390	// the Rust loop can manage click-through independently per window.
391	const petRoot = document.getElementById("pet-root") as HTMLElement;
392	let lastHitSig = "";
393	function reportHitRect() {
394	  const d = window.devicePixelRatio || 1;
395	  const rects: { left: number; top: number; right: number; bottom: number }[] = [];
396	  if (!bubbleEl.hidden) {
397	    const b = bubbleEl.getBoundingClientRect();
398	    if (b.width > 0) rects.push({ left: b.left, top: b.top, right: b.right, bottom: b.bottom });
399	  }
400	  const cr = canvas.getBoundingClientRect();
401	  const sr = pet.spriteRect;
402	  if (sr && canvas.width > 0) {
403	    const kx = cr.width / canvas.width;
404	    const ky = cr.height / canvas.height;
405	    rects.push({
406	      left: cr.left + sr.x * kx,
407	      top: cr.top + sr.y * ky,
408	      right: cr.left + (sr.x + sr.w) * kx,
409	      bottom: cr.top + (sr.y + sr.h) * ky,
410	    });
411	  } else {
412	    rects.push({ left: cr.left, top: cr.top, right: cr.right, bottom: cr.bottom });
413	  }
414	  const left = Math.min(...rects.map((r) => r.left));
415	  const top = Math.min(...rects.map((r) => r.top));
416	  const right = Math.max(...rects.map((r) => r.right));
417	  const bottom = Math.max(...rects.map((r) => r.bottom));
418	  const sig = [left, top, right, bottom].map((v) => Math.round(v)).join(",");
419	  if (sig === lastHitSig) return;
420	  lastHitSig = sig;
421	  invoke("set_hit_rect", { label: MY_LABEL, x: left * d, y: top * d, w: (right - left) * d, h: (bottom - top) * d })
422	    .catch((err) => invoke("log_debug", { msg: `set_hit_rect failed: ${err}` }).catch(() => {}));
423	}
424	new ResizeObserver(reportHitRect).observe(petRoot);
425	window.addEventListener("resize", reportHitRect);
