 45	const canvas = document.getElementById("pet") as HTMLCanvasElement;
 46	const bubbleEl = document.getElementById("bubble") as HTMLDivElement;
 47	const pet = new Pet(canvas);
 48	const store = new ActivityStore();
 49	const bubble = new BubbleRenderer(bubbleEl);
 50	initRoam(pet, () => {
 51	  const instance = myPetInstance();
 52	  return instance
 53	    ? {
 54	      enabled: instance.roamEnabled,
 55	      mode: instance.roamMode,
 56	      speed: instance.roamSpeed,
