 69	// --- bubble appearance (theme / opacity / fonts) ------------------------------
 70	const FONT_FAMILIES: Record<string, string> = {
 71	  system: '"Segoe UI", system-ui, sans-serif',
 72	  rounded: '"Segoe UI Rounded", "Nunito", "Segoe UI", sans-serif',
 73	  mono: 'Consolas, "Courier New", monospace',
 74	};
