 76	function applyBubble() {
 77	  let theme = localStorage.getItem("ap_theme") || "dark";
 78	  if (theme === "system") theme = matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
 79	  const op = (parseInt(localStorage.getItem("ap_opacity") || "92", 10) || 92) / 100;
 80	  const r = document.documentElement.style;
 81	  if (theme === "light") {
 82	    r.setProperty("--bubble-bg", `rgba(255,255,255,${op})`);
 83	    r.setProperty("--bubble-fg", "#3A2C1A");
 84	    r.setProperty("--bubble-border", "rgba(0,0,0,0.08)");
