105	// Simple synthesized chimes (no audio assets needed). Per-event enable, like
106	// the macOS SoundSettings (done = high glass-ish, waiting = lower submarine).
107	let audioCtx: AudioContext | null = null;
108	function chime(event: "done" | "waiting") {
109	  const key = event === "done" ? "ap_sound_done" : "ap_sound_waiting";
110	  const legacy = localStorage.getItem("ap_sound"); // pre-split toggle
111	  const enabled = localStorage.getItem(key) ?? (legacy === "0" ? "0" : "1");
112	  if (enabled === "0") return;
113	  // Custom uploaded sound wins (mac SoundSettings custom file).
114	  const data = localStorage.getItem(`ap_sound_${event}_data`);
115	  if (data) {
116	    try { void new Audio(data).play(); return; } catch {}
117	  }
118	  try {
119	    audioCtx = audioCtx || new AudioContext();
120	    const o = audioCtx.createOscillator();
121	    const g = audioCtx.createGain();
122	    o.type = "sine";
123	    o.frequency.value = event === "done" ? 880 : 560;
124	    g.gain.value = 0.05;
125	    o.connect(g);
126	    g.connect(audioCtx.destination);
127	    o.start();
128	    o.stop(audioCtx.currentTime + 0.13);
129	  } catch {}
130	}
131	
132	// --- pick + load this instance's pet sprite -----------------------------------
133	function loadInstanceSprite() {
134	  const instance = myPetInstance();
135	  if (!instance) return;
136	  const url = libraryUrlForSlug(instance.spriteSlug)
137	    ?? (instance.id === "legacy-pet" ? localStorage.getItem("ap_pet_custom") || localStorage.getItem("ap_pet_url") : null);
138	  if (url) pet.load(url);
139	}
