141	
142	// --- mood + render loop --------------------------------------------------------
143	// Port of PetController: aggregate mood from the activity store, a 3s
144	// celebrate burst when entering done, a persistent idle line (re-picked on
145	// mood transitions, not blinking). Phase 1 has no activity producers yet, so
146	// the pet idles unless a celebrate/level-up flash is triggered (care feeds).
147	let celebrateUntil = 0;
148	let wasCelebrating = false;
149	let moodLine = ""; // the single-bubble line for idle/done/celebrate
150	let celebrateText = "";
151	
152	// Quick bubbles override the normal mood bubble until their own timer expires.
153	// The rendering signature must be invalidated at expiry so a previously cached
154	// idle state cannot leave the quick text visible indefinitely.
155	const QUICK_KEY = "ap_quick_bubbles";
156	let renderSig = "";
157	const quickBubble = new QuickBubbleController({
158	  now: () => Date.now(),
159	  schedule: (callback, delay) => window.setTimeout(callback, delay),
160	  cancel: (timer) => window.clearTimeout(timer as number),
161	}, () => {
162	  renderSig = "";
