166	function readQuickPresets(): string[] {
167	  try {
168	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
169	    return Array.isArray(v) ? v.filter((x: unknown) => typeof x === "string" && x.trim()) : [];
170	  } catch { return []; }
171	}
172	function randomPreset(): string | null {
173	  const list = readQuickPresets();
174	  if (!list.length) return null;
175	  return list[Math.floor(Math.random() * list.length)];
176	}
177	function showQuickBubble(text: string) {
178	  quickBubble.show(text, readQuickBubbleDurationMs());
179	  render();
180	}
181	/// Play a celebrate burst with a custom line (achievement/level-up), then
182	/// settle back to the aggregate mood (mac PetController.flashCelebrate).
183	function flashCelebrate(line: string) {
184	  celebrateText = line;
185	  celebrateUntil = Date.now() + 3000;
186	  render();
187	}
188	
189	/// Feed this instance through a care mutation; on level-up plays a celebrate
190	/// burst in the same window.
191	export function feedPet(instanceId: string, change: (s: care.CareState) => void) {
192	  const before = care.stateFor(instanceId);
193	  const levelBefore = care.levelForXP(before.xp);
194	  care.mutate(instanceId, change);
195	  const after = care.stateFor(instanceId);
196	  emit("care-updated", { instanceId });
197	  const levelAfter = care.levelForXP(after.xp);
198	  if (levelAfter > levelBefore) {
199	    flashCelebrate(`${t("Level up")}! ${t("Lv")} ${care.displayLevel(after.xp)}`);
200	    chime("done");
201	  }
202	}
203	
204	function pickMoodLine(mood: string) {
205	  // Custom/system pools; working/waiting fall back to the PetChat lines so the
206	  // simple bubble always has something to say.
207	  let pool = bubbleLines(null, mood);
208	  if (!pool.length) pool = PET_CHAT[mood] ?? [];
209	  moodLine = pool.length ? pool[Math.floor(Math.random() * pool.length)] : "";
210	}
211	
212	// Render signature: when nothing changed, skip the DOM writes and IPC calls
213	// entirely. The 500ms timer keeps ticking but becomes a no-op while the pet is
214	// idle, instead of doing a full pass every tick.
215	
216	function render() {
217	  const now = Date.now();
218	  // Quick bubble overrides everything for its configured duration after the
219	  // user sends a message from the floating ball or clicks the pet.
220	  const quickBubbleText = quickBubble.current();
221	  if (quickBubbleText !== null) {
222	    bubble.renderLine(quickBubbleText);
223	    snugBubble();
224	    reportHitRect();
225	    return;
226	  }
227	  const resolved = store.topState() === "done" ? "done" : "idle";
228	  const celebrating = now < celebrateUntil;
229	  const mood = celebrating ? "celebrate" : resolved;
230	  pet.setState(mood);
231	  setMood(mood);
232	  if (celebrating && wasCelebrating && now >= celebrateUntil) {
233	    // burst ended, settle into the actual mood's line
234	    pickMoodLine(resolved === "idle" ? "idle" : "done");
235	  }
236	  wasCelebrating = celebrating;
237	
238	  const sig = [mood, moodLine, celebrating ? celebrateText : ""].join("|");
239	  if (sig !== renderSig) {
240	    renderSig = sig;
241	    if (celebrating) {
242	      bubble.renderLine(celebrateText || t("Done"));
243	    } else if (resolved === "done") {
244	      if (!moodLine) pickMoodLine("done");
245	      bubble.renderLine(moodLine);
246	    } else if (localStorage.getItem("ap_idle") !== "0") {
247	      if (!moodLine) pickMoodLine("idle");
248	      bubble.renderLine(moodLine);
249	    } else {
250	      bubble.hide();
251	    }
252	  }
253	
254	  snugBubble();
255	  reportHitRect();
256	}
257	
258	setInterval(render, 500);
259	// Hunger decays over time, so re-render so the idle line (hunger-aware) can
260	// refresh on the care timer, matching macOS's state-republish trigger.
261	setInterval(() => { moodLine = ""; render(); }, 60_000);
262	
263	// Pull the bubble down over the canvas's empty headroom so it sits right
264	// above the pet's head (the sprite rarely fills the whole canvas height).
265	// Snapped to an integer px so sub-pixel headroom drift between animation
266	// frames doesn't trigger a transform write (and the backdrop-filter re-composite).
267	let lastSnugGap = -Infinity;
268	function snugBubble() {
269	  const gap = Math.floor(Math.max(0, canvas.clientHeight * pet.headroom - 4));
270	  if (gap === lastSnugGap) return;
271	  lastSnugGap = gap;
272	  bubbleEl.style.transform = `translateY(${gap}px)`;
273	}
274	
275	// --- activity events ----------------------------------------------------------
276	// Activity integration is opt-in per desktop instance. The migrated legacy pet
277	// keeps its prior behavior; newly added pets remain independent until enabled.
278	listen<ActivityEventPayload>("activity-event", (e) => {
279	  const instance = myPetInstance();
280	  if (!instance?.reactsToActivity) return;
281	  store.apply(e.payload);
282	  if (e.payload.weight > 0) {
283	    if (e.payload.weight >= 0.5) {
284	      feedPet(instance.id, (state) => care.recordMeal(state, new Date(e.payload.timestamp)));
285	    } else {
286	      feedPet(instance.id, (state) => care.feedTokens(state, Math.max(1, Math.round(e.payload.weight * 10)) * 500, new Date(e.payload.timestamp)));
287	    }
288	  }
