290	});
291	// Instance configuration changes are delivered only to the matching pet window.
292	// Structural changes are handled by native reconciliation and do not require
293	// every existing renderer to reload its sprite.
294	listen<{ instanceId: string }>("pet-instance-changed", (event) => {
295	  if (event.payload.instanceId !== MY_INSTANCE_ID) return;
