316	// --- interactions ------------------------------------------------------------
317	// Manual pointer capture replaces Tauri's native drag loop on Windows. The
318	// controller waits for Rust's interaction lease before moving the transparent
319	// window and finalizes the engine only after its last physical move completes.
320	const LEFT_CLICK_KEY = "ap_left_click_action";
321	
322	function onPetClick() {
323	  const action = (localStorage.getItem(LEFT_CLICK_KEY) || "none") as "none" | "self" | "all";
324	  if (action === "none") return;
325	  const text = randomPreset();
326	  if (!text) return;
327	  if (action === "self") {
328	    showQuickBubble(text);
329	  } else {
330	    emit("quick-bubble", { text, target: "all" });
331	  }
332	}
