334	const petWindowDrag = new WindowDragController({
335	  cursorPosition,
336	  setPosition: moveManualDrag,
337	  startDrag: async () => {
338	    const beginTask = beginManualDrag();
339	    try {
340	      await invoke<void>("set_pet_dragging", { label: MY_LABEL, dragging: true });
341	      await beginTask;
342	    } catch (error) {
343	      finishManualDrag();
344	      await invoke<void>("set_pet_dragging", { label: MY_LABEL, dragging: false });
345	      throw error;
346	    }
347	  },
348	  finishDrag: async () => {
349	    finishManualDrag();
350	    try {
351	      await invoke<void>("persist_pet_position", { label: MY_LABEL });
352	    } finally {
353	      await invoke<void>("set_pet_dragging", { label: MY_LABEL, dragging: false });
354	    }
355	  },
356	}, 4, Number.POSITIVE_INFINITY);
357	
358	attachPetPointerDrag(canvas, {
359	  drag: petWindowDrag,
360	  canBegin: (event) => !pet.spriteRect || pet.hitTest(event.offsetX, event.offsetY),
361	  onBegin: () => { emit("popover-close", null); },
362	  onClick: onPetClick,
363	  now: () => performance.now(),
364	  scale: () => window.devicePixelRatio,
365	  reportError: (error) => console.error("Unable to finish pet drag", error),
366	});
367	
368	attachPetPointerDrag(bubbleEl, {
369	  drag: petWindowDrag,
370	  canBegin: () => true,
371	  onBegin: () => { emit("popover-close", null); },
372	  onClick: () => {},
373	  now: () => performance.now(),
374	  scale: () => window.devicePixelRatio,
375	  reportError: (error) => console.error("Unable to finish pet drag", error),
376	});
377	canvas.addEventListener("contextmenu", (e) => {
378	  e.preventDefault();
379	  invoke("open_settings").catch(() => {});
380	});
381	bubbleEl.addEventListener("contextmenu", (e) => {
382	  e.preventDefault();
383	  invoke("open_settings").catch(() => {});
384	});
