  1	export type Point = {
  2	  x: number;
  3	  y: number;
  4	};
  5	
  6	export type PhysicalPoint = Point;
  7	
  8	export type WindowDragHost = {
  9	  cursorPosition(): Promise<PhysicalPoint>;
 10	  setPosition(position: PhysicalPoint): Promise<void>;
 11	  startDrag(): void | Promise<void>;
 12	  finishDrag(): Promise<void>;
 13	};
 14	
 15	export type WindowDragOutcome = {
 16	  kind: "click" | "drag" | "cancel";
 17	  completion: Promise<void> | null;
 18	};
 19	
 20	type ActiveDrag = {
 21	  pointerId: number;
 22	  startPoint: Point;
 23	  latestPoint: Point;
 24	  grabOffset: PhysicalPoint;
 25	  startedAt: number;
 26	  isDragging: boolean;
 27	  startTask: Promise<boolean>;
 28	  needsMove: boolean;
 29	  moveTask: Promise<void> | null;
 30	  firstMoveError: unknown | null;
 31	};
 32	
 33	export class WindowDragController {
 34	  private active: ActiveDrag | null = null;
 35	
 36	  constructor(
 37	    private readonly host: WindowDragHost,
 38	    private readonly thresholdPx = 4,
 39	    private readonly clickMaxMs = 280,
 40	  ) {}
 41	
 42	  get isDragging(): boolean {
 43	    return this.active?.isDragging ?? false;
 44	  }
 45	
 46	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean {
 47	    if (this.active) return false;
 48	    this.active = {
 49	      pointerId,
 50	      startPoint: point,
 51	      latestPoint: point,
 52	      grabOffset,
 53	      startedAt,
 54	      isDragging: false,
 55	      startTask: Promise.resolve(true),
 56	      needsMove: false,
 57	      moveTask: null,
 58	      firstMoveError: null,
 59	    };
 60	    return true;
 61	  }
 62	
 63	  move(pointerId: number, point: Point): boolean {
 64	    const drag = this.active;
 65	    if (!drag || drag.pointerId !== pointerId) return false;
 66	    drag.latestPoint = point;
 67	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) {
 68	      this.start(drag);
 69	      return true;
 70	    }
 71	    if (drag.isDragging) this.queueMove(drag);
 72	    return false;
 73	  }
 74	
 75	  finish(
 76	    pointerId: number,
 77	    point: Point,
 78	    allowClick: boolean,
 79	    now: number,
 80	  ): WindowDragOutcome | null {
 81	    const drag = this.active;
 82	    if (!drag || drag.pointerId !== pointerId) return null;
 83	
 84	    drag.latestPoint = point;
 85	    this.active = null;
 86	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
 87	    if (!drag.isDragging) {
 88	      return {
 89	        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
 90	        completion: null,
 91	      };
 92	    }
 93	
 94	    this.queueMove(drag);
 95	    return { kind: "drag", completion: this.finishAfterFinalMove(drag) };
 96	  }
 97	
 98	  private movedBeyondThreshold(drag: ActiveDrag): boolean {
 99	    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
100	      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
101	  }
102	
103	  private start(drag: ActiveDrag): void {
104	    drag.isDragging = true;
105	    try {
106	      drag.startTask = Promise.resolve(this.host.startDrag()).then(
107	        () => true,
108	        (error) => {
109	          if (drag.firstMoveError === null) drag.firstMoveError = error;
110	          return false;
111	        },
112	      );
113	    } catch (error) {
114	      if (drag.firstMoveError === null) drag.firstMoveError = error;
115	      drag.startTask = Promise.resolve(false);
116	    }
117	    this.queueMove(drag);
118	  }
119	
120	  private queueMove(drag: ActiveDrag): void {
121	    drag.needsMove = true;
122	    if (drag.moveTask) return;
123	
124	    const task = this.moveToLatestCursorPosition(drag);
125	    drag.moveTask = task;
126	    void task.finally(() => {
127	      if (drag.moveTask === task) drag.moveTask = null;
128	    });
129	  }
130	
131	  private async moveToLatestCursorPosition(drag: ActiveDrag): Promise<void> {
132	    if (!await drag.startTask) return;
133	    while (drag.needsMove) {
134	      drag.needsMove = false;
135	      try {
136	        const cursor = await this.host.cursorPosition();
137	        await this.host.setPosition({
138	          x: cursor.x - drag.grabOffset.x,
139	          y: cursor.y - drag.grabOffset.y,
140	        });
141	      } catch (error) {
142	        if (drag.firstMoveError === null) drag.firstMoveError = error;
143	      }
144	    }
145	  }
146	
147	  private async finishAfterFinalMove(drag: ActiveDrag): Promise<void> {
148	    while (drag.moveTask) {
149	      const task = drag.moveTask;
150	      await task;
151	      if (drag.moveTask === task) break;
152	    }
153	    await this.host.finishDrag();
154	    if (drag.firstMoveError !== null) throw drag.firstMoveError;
155	  }
156	}
  1	import type { PhysicalPoint, Point, WindowDragOutcome } from "./window-drag";
  2	
  3	export type PetPointerDrag = {
  4	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean;
  5	  move(pointerId: number, point: Point): boolean;
  6	  finish(pointerId: number, point: Point, allowClick: boolean, now: number): WindowDragOutcome | null;
  7	};
  8	
  9	export type PetPointerOptions = {
 10	  drag: PetPointerDrag;
 11	  canBegin(event: PointerEvent): boolean;
 12	  onBegin(): void;
 13	  onClick(): void;
 14	  now(): number;
 15	  scale(): number;
 16	  reportError(error: unknown): void;
 17	};
 18	
 19	function gesturePoint(event: PointerEvent): Point {
 20	  return { x: event.screenX, y: event.screenY };
 21	}
 22	
 23	function physicalGrabOffset(event: PointerEvent, scale: number): PhysicalPoint {
 24	  return { x: event.clientX * scale, y: event.clientY * scale };
 25	}
 26	
 27	export function attachPetPointerDrag(element: HTMLElement, options: PetPointerOptions): void {
 28	  let activePointerId: number | null = null;
 29	
 30	  function finish(event: PointerEvent, allowClick: boolean): void {
 31	    if (activePointerId !== event.pointerId) return;
 32	    const outcome = options.drag.finish(event.pointerId, gesturePoint(event), allowClick, options.now());
 33	    activePointerId = null;
 34	    if (element.hasPointerCapture(event.pointerId)) element.releasePointerCapture(event.pointerId);
 35	    if (!outcome) return;
 36	    if (outcome.kind === "click") {
 37	      options.onClick();
 38	      return;
 39	    }
 40	    if (outcome.completion) void outcome.completion.catch(options.reportError);
 41	  }
 42	
 43	  element.addEventListener("pointerdown", (event) => {
 44	    if (event.button !== 0 || activePointerId !== null || !options.canBegin(event)) return;
 45	
 46	    if (!options.drag.begin(
 47	      event.pointerId,
 48	      gesturePoint(event),
 49	      physicalGrabOffset(event, options.scale()),
 50	      options.now(),
 51	    )) return;
 52	    options.onBegin();
 53	    event.preventDefault();
 54	    activePointerId = event.pointerId;
 55	    element.setPointerCapture(event.pointerId);
 56	  });
 57	
 58	  element.addEventListener("pointermove", (event) => {
 59	    if (activePointerId !== event.pointerId) return;
 60	    options.drag.move(event.pointerId, gesturePoint(event));
 61	  });
 62	
 63	  element.addEventListener("pointerup", (event) => finish(event, true));
 64	  element.addEventListener("pointercancel", (event) => finish(event, false));
 65	  element.addEventListener("lostpointercapture", (event) => finish(event, false));
 66	}

