  1	// Movement engine: owns the tick loop, coordinates drag sampling, throw/fall
  2	// physics, and dispatches to the active movement mode.
  3	
  4	import { invoke } from "@tauri-apps/api/core";
  5	import { getCurrentWindow } from "@tauri-apps/api/window";
  6	import type { Pet } from "../pet";
  7	import { fetchEnvironment } from "./environment";
  8	import { runMode } from "./modes";
  9	import {
 10	  applyFall,
 11	  applyThrow,
 12	  cancelThrow,
 13	  clearSamples,
 14	  isThrowing,
 15	  recordSample,
 16	  releaseVelocity,
 17	} from "./physics";
 18	import type { Config, Environment, Point, RoamMode } from "./types";
 19	import {
 20	  SLEEP_AFTER_MS,
 21	  SLEEP_ROW_DEFAULT,
 22	  THROW_MIN_SPEED,
 23	  TICK_MS,
 24	  clampToBounds,
 25	  loadConfig,
 26	  sleep,
 27	} from "./types";
 28	import { currentLogicalPos, setDragPositionTracking, setLogical, setPhysical } from "./window";
 29	
 30	/// Tick delay when the pet is resting / sleeping / stationary. The active
 31	/// TICK_MS (30ms) is only needed while the pet is actually moving — resting
 32	/// states (restUntil, sleep, stay mode) only need to check periodically whether
 33	/// to wake up. 200ms cuts IPC calls from 33/sec to 5/sec while idle, with no
 34	/// visible change (the pet resumes walking within one idle-tick of restUntil
 35	/// expiring, imperceptible for a desktop companion).
 36	const IDLE_TICK_MS = 200;
 37	
 38	let petRef: Pet | null = null;
 39	let dragging = false;
 40	let releasePending = false;
 41	let stopRequested = false;
 42	
 43	/// Mood drives two behaviors: pause roaming while the user needs to read the
 44	/// bubble (waiting / celebrate), and let the pet doze off when idle.
 45	let mood: string = "idle";
 46	let lastMoveTs = Date.now();
 47	let sleeping = false;
 48	
 49	/// Moods that freeze the pet so the bubble / celebration animation stays readable.
 50	const MOOD_PAUSES_ROAM = new Set(["waiting", "celebrate"]);
 51	
 52	function stop(): boolean { return stopRequested; }
 53	
 54	/// Called from main.ts after each mood evaluation. Non-idle moods wake the pet.
 55	export function setMood(m: string): void {
 56	  mood = m;
 57	  if (m !== "idle") wake();
 58	}
 59	
 60	function wake(): void {
 61	  if (!sleeping) return;
 62	  sleeping = false;
 63	  petRef?.clearRow();
 64	}
 65	
 66	function enterSleep(): void {
 67	  if (sleeping) return;
 68	  sleeping = true;
 69	  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
 70	  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
 71	  petRef?.setRow(row);
 72	}
 73	
 74	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 75	/// Returns true when the pet is actively moving/interacting and needs the fast
 76	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 77	/// idle (200ms) tick and skip most IPC calls.
 78	async function tick(): Promise<boolean> {
 79	  if (isThrowing()) return true;
 80	  if (dragging) {
 81	    const pos = await currentLogicalPos();
 82	    if (pos) recordSample(pos);
 83	    return true;
 84	  }
 85	  if (releasePending) {
 86	    releasePending = false;
 87	    const vel = releaseVelocity();
 88	    clearSamples();
 89	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 90	      wake();
 91	      await handleDragRelease(vel);
 92	      return true;
 93	    }
 94	  }
 95	
 96	  // Mood-driven freeze: keep the pet still while the user needs to see the
 97	  // bubble or the celebrate burst. Throws and drags above still work.
 98	  if (MOOD_PAUSES_ROAM.has(mood)) {
 99	    wake();
100	    petRef?.clearRow();
101	    return false;
102	  }
103	
104	  const cfg = loadConfig();
105	  if (!cfg.enabled || cfg.mode === "stay") {
106	    handleStationary();
107	    return false;
108	  }
109	
110	  wake();
111	  const moved = await stepMode(cfg.mode);
112	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
113	    enterSleep();
114	  }
115	  return moved;
116	}
117	
118	/// Run one mode step and apply it. Returns true if the pet actually moved.
119	async function stepMode(mode: RoamMode): Promise<boolean> {
120	  const env = await fetchEnvironment(mode === "climb");
121	  if (!env) return false;
122	  const pos = await currentLogicalPos();
123	  if (!pos) return false;
124	
125	  const next = await runMode(mode, { env, pos, pet: petRef });
126	  const clamped = clampToBounds(next, env.workArea);
127	  const moved = Math.abs(clamped.x - pos.x) >= 0.5 || Math.abs(clamped.y - pos.y) >= 0.5;
128	  if (!moved) {
129	    return false;
130	  }
131	  lastMoveTs = Date.now();
132	  try { await setLogical(clamped); }
133	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
134	  return true;
135	}
136	
137	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
138	function handleStationary(): void {
139	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
140	    enterSleep();
141	  } else {
142	    wake();
143	    petRef?.clearRow();
144	  }
145	}
146	
147	type ReleaseContext = {
148	  config: Config;
149	  environment: Environment;
150	};
151	
152	type ConfigReader = () => Config;
153	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
154	
155	export async function resolveReleaseContext(
156	  getConfig: ConfigReader = loadConfig,
157	  getEnvironment: EnvironmentReader = fetchEnvironment,
158	): Promise<ReleaseContext | null> {
159	  let config = getConfig();
160	  const includedSystemWindows = config.mode === "climb";
161	  let environment = await getEnvironment(includedSystemWindows);
162	  if (!environment) return null;
163	
164	  config = getConfig();
165	  if (config.mode === "climb" && !includedSystemWindows) {
166	    environment = await getEnvironment(true);
167	    if (!environment) return null;
168	  }
169	
170	  return { config: getConfig(), environment };
171	}
172	
173	async function persistPetPosition(): Promise<void> {
174	  try {
175	    await invoke<void>("persist_pet_position", { label: getCurrentWindow().label });
176	  } catch (error) {
177	    console.error("Unable to persist pet position", error);
178	  }
179	}
180	
181	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
182	  const context = await resolveReleaseContext();
183	  if (!context) return;
184	  const { config: cfg, environment: env } = context;
185	
186	  if (cfg.mode === "climb" && env.windows.length > 0) {
187	    const surfaces = env.windows.map((w) => w.rect);
188	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
189	  } else {
190	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
191	  }
192	  await persistPetPosition();
193	}
194	
195	async function loop(): Promise<void> {
196	  while (!stopRequested) {
197	    const active = await tick();
198	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
199	  }
200	  petRef?.clearRow();
201	}
202	
203	export function initEngine(pet: Pet): void {
204	  if (petRef) return;
205	  petRef = pet;
206	  stopRequested = false;
207	  lastMoveTs = Date.now();
208	  mood = "idle";
209	  sleeping = false;
210	  void loop();
211	}
212	
213	export function destroyEngine(): void {
214	  stopRequested = true;
215	  cancelThrow();
216	  petRef = null;
217	}
218	
219	export function setDragging(isDragging: boolean): void {
220	  dragging = isDragging;
221	  setDragPositionTracking(isDragging);
222	  if (isDragging) {
223	    cancelThrow();
224	    clearSamples();
225	    wake();
226	    releasePending = false;
227	  } else if (petRef) {
228	    releasePending = true;
229	  }
230	}
231	
232	/// Starts a pointer-managed drag after its native interaction lease is active.
233	/// The starting position is sampled explicitly so a quick drag need not wait
234	/// for two engine ticks before it can produce a throw velocity.
235	export async function beginManualDrag(): Promise<void> {
236	  setDragging(true);
237	  const position = await currentLogicalPos();
238	  if (position && dragging) recordSample(position);
239	}
240	
241	/// Moves the window in physical coordinates and records every successful
242	/// manual position in the same logical coordinate system used by physics.
243	export async function moveManualDrag(position: Point): Promise<void> {
244	  const logicalPosition = await setPhysical(position);
245	  if (dragging) recordSample(logicalPosition);
246	}
247	
248	export function finishManualDrag(): void {
