  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition, PhysicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	let cachedLogicalPos: Point | null = null;
 13	let cacheGeneration = 0;
 14	let pendingPositionRead: Promise<Point | null> | null = null;
 15	let pendingNativeDragMove: Promise<void> | null = null;
 16	let nativeDragActive = false;
 17	let trackingStarted = false;
 18	let pendingTracking: Promise<void> | null = null;
 19	
 20	function copyPoint(pos: Point): Point {
 21	  return { x: pos.x, y: pos.y };
 22	}
 23	
 24	function invalidatePosition(): number {
 25	  cacheGeneration += 1;
 26	  cachedLogicalPos = null;
 27	  return cacheGeneration;
 28	}
 29	
 30	function refreshNativeDragPosition(physical: Point): void {
 31	  const generationAtMove = invalidatePosition();
 32	  let update: Promise<void>;
 33	  update = win.scaleFactor()
 34	    .then((scaleFactor) => {
 35	      if (!nativeDragActive || generationAtMove !== cacheGeneration) return;
 36	      cachedLogicalPos = {
 37	        x: physical.x / scaleFactor,
 38	        y: physical.y / scaleFactor,
 39	      };
 40	    })
 41	    .catch(() => {
 42	      // Keep the cache invalid; the regular reader retries when it is needed.
 43	    })
 44	    .finally(() => {
 45	      if (pendingNativeDragMove === update) pendingNativeDragMove = null;
 46	    });
 47	  pendingNativeDragMove = update;
 48	}
 49	
 50	function startPositionTracking(): void {
 51	  if (trackingStarted || pendingTracking) return;
 52	  const movedRegistration = Promise.resolve().then(() =>
 53	    win.onMoved(({ payload }) => {
 54	      if (nativeDragActive) refreshNativeDragPosition(payload);
 55	    }),
 56	  );
 57	  const scaleRegistration = Promise.resolve().then(() =>
 58	    win.onScaleChanged(() => {
 59	      invalidatePosition();
 60	    }),
 61	  );
 62	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
 63	    .then(([moved, scale]) => {
 64	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
 65	        trackingStarted = true;
 66	        return;
 67	      }
 68	      if (moved.status === "fulfilled") moved.value();
 69	      if (scale.status === "fulfilled") scale.value();
 70	    })
 71	    .finally(() => {
 72	      pendingTracking = null;
 73	    });
 74	}
 75	
 76	export function setDragPositionTracking(active: boolean): void {
 77	  if (nativeDragActive === active) return;
 78	  nativeDragActive = active;
 79	  invalidatePosition();
 80	}
 81	
 82	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 83	/// window or scaleFactor can't be read (e.g. window closing).
 84	export async function currentLogicalPos(): Promise<Point | null> {
 85	  startPositionTracking();
 86	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 87	  while (pendingNativeDragMove) {
 88	    const update = pendingNativeDragMove;
 89	    await update;
 90	    if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 91	    if (pendingNativeDragMove === update) break;
 92	  }
 93	  if (!pendingPositionRead) {
 94	    const generationAtReadStart = cacheGeneration;
 95	    pendingPositionRead = (async () => {
 96	      try {
 97	        const sf = await win.scaleFactor();
 98	        const p = await win.outerPosition();
 99	        if (generationAtReadStart !== cacheGeneration) {
100	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
101	        }
102	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
103	        return copyPoint(cachedLogicalPos);
104	      } catch {
105	        return null;
106	      } finally {
107	        pendingPositionRead = null;
108	      }
109	    })();
110	  }
111	  const pos = await pendingPositionRead;
112	  return pos ? copyPoint(pos) : null;
113	}
114	
115	/// Move the window to a physical-pixel position and return its corresponding
116	/// logical position for roam sampling.
117	export async function setPhysical(pos: Point): Promise<Point> {
118	  const generationAtSetStart = invalidatePosition();
119	  await win.setPosition(new PhysicalPosition(pos.x, pos.y));
120	  const scaleFactor = await win.scaleFactor();
121	  const logical = { x: pos.x / scaleFactor, y: pos.y / scaleFactor };
122	  if (generationAtSetStart === cacheGeneration) cachedLogicalPos = copyPoint(logical);
123	  return logical;
124	}
125	
126	/// Move the window to a logical-pixel position. Caller is responsible for
127	/// clamping to the work area first.
128	export async function setLogical(pos: Point): Promise<void> {
129	  const generationAtSetStart = invalidatePosition();
130	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
131	  if (generationAtSetStart === cacheGeneration && !nativeDragActive) {
132	    cachedLogicalPos = copyPoint(pos);
133	  }
134	}

