147	type ReleaseContext = {
148	  config: Config;
149	  environment: Environment;
150	};
151	
152	type ConfigReader = () => Config;
153	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
154	
155	export async function resolveReleaseContext(
156	  getConfig: ConfigReader = loadConfig,
157	  getEnvironment: EnvironmentReader = fetchEnvironment,
158	): Promise<ReleaseContext | null> {
159	  let config = getConfig();
160	  const includedSystemWindows = config.mode === "climb";
161	  let environment = await getEnvironment(includedSystemWindows);
162	  if (!environment) return null;
163	
164	  config = getConfig();
165	  if (config.mode === "climb" && !includedSystemWindows) {
166	    environment = await getEnvironment(true);
167	    if (!environment) return null;
168	  }
169	
170	  return { config: getConfig(), environment };
171	}
172	
173	async function persistPetPosition(): Promise<void> {
174	  try {
175	    await invoke<void>("persist_pet_position", { label: getCurrentWindow().label });
176	  } catch (error) {
177	    console.error("Unable to persist pet position", error);
178	  }
179	}
180	
181	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
182	  const context = await resolveReleaseContext();
183	  if (!context) return;
184	  const { config: cfg, environment: env } = context;
185	
186	  if (cfg.mode === "climb" && env.windows.length > 0) {
187	    const surfaces = env.windows.map((w) => w.rect);
188	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
189	  } else {
190	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
191	  }
192	  await persistPetPosition();
193	}
194	
195	async function loop(): Promise<void> {
196	  while (!stopRequested) {
197	    const active = await tick();
198	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
199	  }
200	  petRef?.clearRow();
201	}
