   272	/// Logical size of the primary monitor's work area (DPI-divided). Returns a
   273	/// safe fallback (1920×1080) if the monitor can't be read , spawns must never
   274	/// land off-screen on display hotplug / headless CI.
   275	fn primary_work_area(app: &tauri::AppHandle) -> (f64, f64) {
   276	    app.primary_monitor()
   277	        .ok()
   278	        .flatten()
   279	        .and_then(|m| {
   280	            let s = m.size();
   281	            let sf = m.scale_factor();
   282	            if s.width > 0 && s.height > 0 {
   283	                Some((s.width as f64 / sf, s.height as f64 / sf))
   284	            } else {
   285	                None
   286	            }
   287	        })
   288	        .unwrap_or((1920.0, 1080.0))
   289	}
