   339	fn build_desktop_pet_window(
   340	    app: &tauri::AppHandle,
   341	    instance: &DesktopPetWindow,
   342	    index: usize,
   343	) -> Result<(), String> {
   344	    let label = pet_window_label(&instance.id);
   345	    if let Some(window) = app.get_webview_window(&label) {
   346	        if instance.visible && read_desktop_pets_visible() {
   347	            window.show().map_err(|error| error.to_string())?;
   348	        } else {
   349	            window.hide().map_err(|error| error.to_string())?;
   350	        }
   351	        return Ok(());
   352	    }
   353	
   354	    let url = format!("index.html?pet={}", instance.id);
   355	    let mut builder = WebviewWindowBuilder::new(app, &label, WebviewUrl::App(url.into()))
   356	        .title("DesktopPet")
   357	        .inner_size(260.0, 320.0)
   358	        .transparent(true)
   359	        .decorations(false)
   360	        .always_on_top(true)
   361	        .skip_taskbar(true)
   362	        .resizable(false)
   363	        .shadow(false)
   364	        .focused(false)
   365	        .visible(instance.visible && read_desktop_pets_visible());
   366	    builder = match saved_pet_position(app, &instance.id) {
   367	        Some((x, y)) => {
   368	            let (x, y) = logical_position_for_physical(app, x, y);
   369	            builder.position(x, y)
   370	        }
   371	        None => {
   372	            let (x, y) = default_pet_position(app, index);
   373	            builder.position(x, y)
   374	        }
   375	    };
   376	    builder.build().map_err(|error| error.to_string())?;
   377	    Ok(())
   378	}
