   380	fn sync_desktop_pet_windows_impl(app: tauri::AppHandle, pets: Vec<DesktopPetWindow>) {
   381	    use std::collections::HashSet;
   382	    let wanted: HashSet<String> = pets.iter().map(|pet| pet_window_label(&pet.id)).collect();
   383	    for (label, window) in app.webview_windows() {
   384	        if is_pet_window(&label) && !wanted.contains(&label) {
   385	            let _ = window.close();
   386	        }
   387	    }
   388	    for (index, pet) in pets.iter().enumerate() {
   389	        if let Err(error) = build_desktop_pet_window(&app, pet, index) {
   390	            dlog(&format!("desktop pet window failed for {}: {error}", pet.id));
   391	        }
   392	    }
   393	}
