   469	/// Spawn the floating ball window if it doesn't exist yet. Position is restored
   470	/// from disk (clamped onto a monitor) or defaulted to the bottom-right corner.
   471	/// Must be called from a worker thread, like open_settings_impl.
   472	fn spawn_floating_ball_impl(app: tauri::AppHandle) {
   473	    if app.get_webview_window(FLOATING_BALL_LABEL).is_some() {
   474	        return;
   475	    }
   476	    let (sw, sh) = primary_work_area(&app);
   477	    let (x, y) = read_ball_pos()
   478	        .filter(|&(x, y)| x >= 0.0 && x <= sw && y >= 0.0 && y <= sh)
   479	        .unwrap_or_else(|| (sw - BALL_W - 24.0, sh - BALL_H - 80.0));
   480	    let _ = WebviewWindowBuilder::new(
   481	        &app,
   482	        FLOATING_BALL_LABEL,
   483	        WebviewUrl::App("floating-ball.html".into()),
   484	    )
   485	    .title("DesktopPet")
   486	    .inner_size(BALL_W, BALL_H)
   487	    .position(x.max(0.0), y.max(0.0))
   488	    .transparent(true)
   489	    .decorations(false)
   490	    .always_on_top(true)
   491	    .skip_taskbar(true)
   492	    .resizable(false)
   493	    .shadow(false)
   494	    .focused(false)
   495	    .build();
   496	}
