   555	/// Show the popover (the macOS menu-bar popover equivalent) near the cursor.
   556	fn show_popover(app: &tauri::AppHandle) {
   557	    let win = match app.get_webview_window("popover") {
   558	        Some(w) => w,
   559	        None => {
   560	            match WebviewWindowBuilder::new(app, "popover", WebviewUrl::App("popover.html".into()))
   561	                .title("DesktopPet")
   562	                .inner_size(300.0, 430.0)
   563	                .decorations(false)
   564	                .transparent(true)
   565	                .always_on_top(true)
   566	                .skip_taskbar(true)
   567	                .resizable(false)
   568	                .focused(true)
   569	                .visible(false)
   570	                .build()
   571	            {
   572	                Ok(w) => {
   573	                    dlog("popover: window created");
   574	                    // Transient popover: losing focus hides it (Rust-side net,
   575	                    // independent of the webview's own blur listener).
   576	                    let wh = w.clone();
   577	                    w.on_window_event(move |ev| {
   578	                        if let tauri::WindowEvent::Focused(false) = ev {
   579	                            let _ = wh.hide();
   580	                        }
   581	                    });
   582	                    w
   583	                }
   584	                Err(e) => {
   585	                    dlog(&format!("popover: BUILD FAILED: {e}"));
   586	                    return;
   587	                }
   588	            }
   589	        }
   590	    };
   591	    // Place near the cursor, clamped onto the monitor under it.
   592	    if let Ok(cur) = app.cursor_position() {
   593	        let sf = win.scale_factor().unwrap_or(1.0);
   594	        let (w, h) = (300.0 * sf, 430.0 * sf);
   595	        let mut x = cur.x - w / 2.0;
   596	        let mut y = cur.y - h - 12.0; // prefer above the cursor (tray at bottom)
   597	        if let Ok(Some(mon)) = app.monitor_from_point(cur.x, cur.y) {
   598	            let mp = mon.position();
   599	            let ms = mon.size();
   600	            if y < mp.y as f64 {
   601	                y = cur.y + 12.0; // no room above , drop below
   602	            }
   603	            x = x.max(mp.x as f64).min(mp.x as f64 + ms.width as f64 - w);
   604	            y = y.max(mp.y as f64).min(mp.y as f64 + ms.height as f64 - h);
   605	        }
   606	        let _ = win.set_position(PhysicalPosition::new(x, y));
   607	    }
   608	    let _ = win.show();
   609	    let _ = win.set_focus();
   610	    let _ = win.emit("popover-shown", ());
   611	}
