   323	fn logical_position_for_physical(app: &tauri::AppHandle, x: i32, y: i32) -> (f64, f64) {
   324	    let scale_factor = app.available_monitors()
   325	        .ok()
   326	        .and_then(|monitors| monitors.into_iter().find(|monitor| {
   327	            let position = monitor.position();
   328	            let size = monitor.size();
   329	            x >= position.x
   330	                && x < position.x + size.width as i32
   331	                && y >= position.y
   332	                && y < position.y + size.height as i32
   333	        }))
   334	        .map(|monitor| monitor.scale_factor())
   335	        .unwrap_or(1.0);
   336	    (x as f64 / scale_factor, y as f64 / scale_factor)
   337	}
