   558	        Some(w) => w,
   559	        None => {
   560	            match WebviewWindowBuilder::new(app, "popover", WebviewUrl::App("popover.html".into()))
   561	                .title("DesktopPet")
   562	                .inner_size(300.0, 430.0)
   563	                .decorations(false)
   564	                .transparent(true)
   565	                .always_on_top(true)
   566	                .skip_taskbar(true)
   567	                .resizable(false)
   568	                .focused(true)
   569	                .visible(false)
   570	                .build()
   571	            {
   572	                Ok(w) => {
   573	                    dlog("popover: window created");
   574	                    // Transient popover: losing focus hides it (Rust-side net,
   575	                    // independent of the webview's own blur listener).
   576	                    let wh = w.clone();
