 83	  const list = readPresets();
 84	  presetsEl.innerHTML = "";
 85	  if (!list.length) {
 86	    presetsEl.style.display = "none";
 87	    return;
 88	  }
 89	  presetsEl.style.display = "";
 90	  list.forEach((line, i) => presetsEl.appendChild(createPresetButton(line, i)));
 91	}
 92	
 93	function applyLangStrings() {
 94	  const bmTitle = document.getElementById("bm-title-text");
 95	  if (bmTitle) bmTitle.textContent = t("Quick bubble");
 96	  const bmHint = document.getElementById("bm-hint");
 97	  if (bmHint) bmHint.textContent = t("Shift-click to remove");
 98	  input.placeholder = t("Type a bubble message…");
 99	  cancelBtn.textContent = t("Cancel");
100	  sendBtn.textContent = t("Send");
101	  ball.title = t("Left-click: bubble · Right-click: settings · Drag to move");
102	}
103	
104	function shrinkToBall() {
105	  void win.setSize(new LogicalSize(WIN_SIZE, WIN_SIZE));
106	}
107	
108	/// Height delta between the menu window and the ball window.
109	const MENU_GROW = MENU_H - WIN_SIZE;
110	
111	async function showMenu() {
112	  if (!menu.hidden) return;
113	  input.value = "";
114	  selectedPreset = -1;
115	  paintPresets();
116	  syncSend();
117	
118	  const pos = await win.outerPosition();
119	  const sf = await win.scaleFactor();
120	  const mon = await currentMonitor();
121	  const work = mon?.workArea;
122	  const logicalX = pos.x / sf;
123	  const logicalY = pos.y / sf;
124	  const workLeft = work ? work.position.x / sf : logicalX;
125	  const workTop = work ? work.position.y / sf : logicalY;
126	  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
127	  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;
128	
129	  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
130	  // the bottom of the window and the menu sits above it. The window's Y
131	  // moves up by MENU_GROW so the ball's screen position is preserved.
132	  const openAbove = logicalY + MENU_H > workBottom;
133	  // Adjust X so the wider menu window stays on-screen.
134	  let newX = logicalX;
135	  if (newX + MENU_W > workRight) newX = workRight - MENU_W;
136	  if (newX < workLeft) newX = workLeft;
137	  let newY = logicalY;
138	  if (openAbove) newY = logicalY - MENU_GROW;
139	  // Clamp Y so the window never starts above the work area.
140	  if (newY < workTop) newY = workTop;
141	
142	  document.body.classList.toggle("menu-above", openAbove);
143	  if (Math.abs(newX - logicalX) > 0.5 || Math.abs(newY - logicalY) > 0.5) {
144	    void win.setPosition(new LogicalPosition(newX, newY));
145	  }
146	  // Resize FIRST, then reveal the menu, so the menu never appears clipped
147	  // inside the still-80×80 window for a frame.
148	  await win.setSize(new LogicalSize(MENU_W, MENU_H));
149	  menu.hidden = false;
150	  requestAnimationFrame(() => input.focus());
151	}
152	
153	function hideMenu() {
154	  if (menu.hidden) return;
155	  menu.hidden = true;
156	  const wasAbove = document.body.classList.contains("menu-above");
157	  document.body.classList.remove("menu-above");
158	  shrinkToBall();
159	  if (wasAbove) {
160	    // Window was shifted up by MENU_GROW to open the menu above.
161	    // Move it back down so the ball returns to its original screen position.
162	    void (async () => {
163	      const pos = await win.outerPosition();
164	      const sf = await win.scaleFactor();
165	      void win.setPosition(new LogicalPosition(pos.x / sf, pos.y / sf + MENU_GROW));
166	    })();
167	  }
168	}
169	
170	function send() {
171	  const text = input.value.trim();
172	  if (!text) return;
173	  const next = [text, ...readPresets().filter((x) => x !== text)];
174	  writePresets(next);
175	  void emit("quick-bubble", { text });
176	  hideMenu();
177	}
178	
179	// ---- click vs drag ---------------------------------------------------------
180	// Tauri's native startDragging can lose mouseup on Windows, leaving the window
181	// attached to the cursor. Pointer capture keeps the interaction in the webview.
182	attachFloatingBallPointerDrag(ball, {
183	  drag: floatingBallDrag,
184	  isMenuOpen: () => !menu.hidden,
185	  hideMenu,
186	  showMenu,
187	  now: () => performance.now(),
188	  scale: () => window.devicePixelRatio,
189	  reportError: (error) => console.error("Unable to finish floating ball drag", error),
190	});
191	
192	ball.addEventListener("contextmenu", (e) => {
193	  e.preventDefault();
194	  hideMenu();
195	  void invoke("open_settings");
196	});
197	
198	// ---- menu interactions -----------------------------------------------------
199	input.addEventListener("input", () => { selectedPreset = -1; paintPresets(); syncSend(); });
200	input.addEventListener("keydown", (e) => {
201	  if (e.key === "Enter" && input.value.trim()) { e.preventDefault(); send(); }
202	  else if (e.key === "Escape") { hideMenu(); }
203	});
204	
205	cancelBtn.onclick = () => hideMenu();
206	sendBtn.onclick = () => send();
207	
208	// Dismiss menu on Escape or when the window loses focus.
209	window.addEventListener("keydown", (e) => { if (e.key === "Escape" && !menu.hidden) hideMenu(); });
210	window.addEventListener("blur", () => { if (!menu.hidden) hideMenu(); });
211	
212	// ---- live updates ----------------------------------------------------------
213	function applyReduceMotion() {
214	  document.body.classList.toggle("reduce-motion", localStorage.getItem("ap_reduce_motion") === "1");
215	}
216	applyReduceMotion();
217	window.addEventListener("storage", (e) => { if (e.key === "ap_reduce_motion") applyReduceMotion(); });
218	
219	applyLangStrings();
220	paintPresets();
221	syncSend();
222	void listen("bubble-changed", () => paintPresets());
223	void listen<Lang>("lang-changed", (e) => { setLang(e.payload); applyLangStrings(); paintPresets(); });
224	
225	// ---- living pet inside the orb: mirror the instance selected in Settings.
226	const ballCanvas = document.getElementById("ball-pet") as HTMLCanvasElement | null;
227	let ballPet: Pet | null = null;
228	
229	function loadBallPet(): void {
230	  const store = loadPetStore();
231	  const instance = store ? selectedPetInstance(store) : null;
232	  const pet = getLibrary().find((candidate) => candidate.slug === instance?.spriteSlug) ?? getLibrary()[0];
233	  if (pet) ballPet?.load(pet.url);
234	}
235	
236	if (ballCanvas) {
237	  ballPet = new Pet(ballCanvas);
238	  loadBallPet();
239	}
240	void listen("pets-changed", loadBallPet);

