  1	// Environment sensing: monitor work area + enumeration of other application
  2	// windows. All geometry is returned in logical pixels so the rest of the roam
  3	// subsystem can stay DPI-agnostic.
  4	
  5	import { currentMonitor, type Monitor } from "@tauri-apps/api/window";
  6	import { invoke } from "@tauri-apps/api/core";
  7	import type { Environment, Rect, SystemWindow } from "./types";
  8	
  9	/// Raw shape returned by the Rust `list_system_windows` command. Coordinates
 10	/// are physical pixels; we convert to logical in `fetchEnvironment`.
 11	interface RawSystemWindow {
 12	  title: string;
 13	  x: number;
 14	  y: number;
 15	  width: number;
 16	  height: number;
 17	}
 18	
 19	function toLogicalRect(rect: RawSystemWindow, sf: number): SystemWindow {
 20	  return {
 21	    title: rect.title,
 22	    rect: {
 23	      left: rect.x / sf,
 24	      top: rect.y / sf,
 25	      right: (rect.x + rect.width) / sf,
 26	      bottom: (rect.y + rect.height) / sf,
 27	    },
 28	  };
 29	}
 30	
 31	// 500ms monitor cache: the monitor rarely changes (only when the user drags
 32	// the pet to another display), and currentMonitor() is an IPC call. Without
 33	// this, N roaming pets fire 2×N×33 IPC calls/sec just for monitor info.
 34	const MONITOR_CACHE_MS = 500;
 35	let monitorCache: { mon: Monitor | null; ts: number } | null = null;
 36	
 37	async function cachedMonitor(): Promise<Monitor | null> {
 38	  const now = Date.now();
 39	  if (monitorCache && now - monitorCache.ts < MONITOR_CACHE_MS) {
 40	    return monitorCache.mon;
 41	  }
 42	  try {
 43	    const m = await currentMonitor();
 44	    monitorCache = { mon: m, ts: now };
 45	    return m;
 46	  } catch {
 47	    return null;
 48	  }
 49	}
 50	
 51	// 500ms system-windows cache: list_system_windows is an IPC call that enumerates
 52	// every visible window. Other apps' window positions change far less often than
 53	// the 30ms roam tick, so caching avoids ~33 IPC calls/sec per roaming pet. The
 54	// cache is keyed by the monitor scale factor so a monitor switch still refetches.
 55	const WIN_CACHE_MS = 500;
 56	let winCache: { sf: number; windows: SystemWindow[]; ts: number } | null = null;
 57	
 58	async function fetchSystemWindows(sf: number): Promise<SystemWindow[]> {
 59	  const now = Date.now();
 60	  if (winCache && winCache.sf === sf && now - winCache.ts < WIN_CACHE_MS) {
 61	    return winCache.windows;
 62	  }
 63	  try {
 64	    const raw = await invoke<RawSystemWindow[]>("list_system_windows");
 65	    if (!Array.isArray(raw)) return winCache?.windows ?? [];
 66	    const windows = raw
 67	      .filter((w) => w.width > 40 && w.height > 40)
 68	      .map((w) => toLogicalRect(w, sf));
 69	    winCache = { sf, windows, ts: now };
 70	    return windows;
 71	  } catch {
 72	    return winCache?.windows ?? [];
 73	  }
 74	}
 75	
 76	export function invalidateEnvironmentCache(): void {
 77	  winCache = null;
 78	  monitorCache = null;
 79	}
 80	
 81	export async function fetchEnvironment(includeSystemWindows = false): Promise<Environment | null> {
 82	  try {
 83	    // Single currentMonitor() call (cached) instead of the previous two.
 84	    const m = await cachedMonitor();
 85	    if (!m || !m.workArea) return null;
 86	    const sf = m.scaleFactor || 1;
 87	    const wa = m.workArea;
 88	    const workArea: Rect = {
 89	      left: wa.position.x / sf,
 90	      top: wa.position.y / sf,
 91	      right: (wa.position.x + wa.size.width) / sf,
 92	      bottom: (wa.position.y + wa.size.height) / sf,
 93	    };
 94	
 95	    const windows = includeSystemWindows ? await fetchSystemWindows(sf) : [];
 96	    return { workArea, windows };
 97	  } catch (e) {
 98	    void invoke("log_debug", { msg: `roam: environment error: ${e}` }).catch(() => {});
 99	    return null;
100	  }
101	}
  1	// Shared types and constants for the roam subsystem.
  2	
  3	import { getCurrentWindow } from "@tauri-apps/api/window";
  4	import {
  5	  DEFAULT_WANDER_PAUSE_MAX_MS,
  6	  DEFAULT_WANDER_PAUSE_MIN_MS,
  7	  normalizeWanderPauseRange,
  8	} from "./pause";
  9	
 10	export type RoamMode = "stay" | "wander" | "cursor" | "climb";
 11	
 12	export type Point = { x: number; y: number };
 13	
 14	export type Rect = {
 15	  left: number;
 16	  top: number;
 17	  right: number;
 18	  bottom: number;
 19	};
 20	
 21	export type SystemWindow = {
 22	  title: string;
 23	  rect: Rect;
 24	};
 25	
 26	export type Environment = {
 27	  /// Work area of the current monitor (excludes taskbar), in logical pixels.
 28	  workArea: Rect;
 29	  /// Other application windows visible on screen, in logical pixels.
 30	  /// Empty on platforms where enumeration is unavailable.
 31	  windows: SystemWindow[];
 32	};
 33	
 34	export type Config = {
 35	  enabled: boolean;
 36	  mode: RoamMode;
 37	  speed: number;
 38	  wanderPauseMinMs: number;
 39	  wanderPauseMaxMs: number;
 40	};
 41	
 42	export type ConfigSource = () => Config;
 43	
 44	export const ROAM_KEY = "ap_roam";
 45	export const ROAM_MODE_KEY = "ap_roam_mode";
 46	export const ROAM_SPEED_KEY = "ap_roam_speed";
 47	
 48	export const WIN_W = 260;
 49	export const WIN_H = 320;
 50	export const MARGIN = 40;
 51	
 52	export const IDLE_MS_MIN = 1200;
 53	export const IDLE_MS_MAX = 3500;
 54	
 55	export const PHYSICS_FRICTION = 0.9;
 56	export const PHYSICS_MIN_SPEED = 15;
 57	export const PHYSICS_GRAVITY = 1800;
 58	export const SAMPLE_WINDOW_MS = 120;
 59	
 60	export const TICK_MS = 30;
 61	/// Fixed dt (seconds) used by physics integration. Derived from TICK_MS so the
 62	/// two can never drift apart. All `vx * 0.03` style computations use this.
 63	export const DT_SEC = TICK_MS / 1000;
 64	
 65	/// Below this drag-release speed (px/s), no throw is applied , the pet just stays.
 66	export const THROW_MIN_SPEED = 15;
 67	
 68	/// Pet falls asleep after this many ms idle with no movement (Oneko-style).
 69	export const SLEEP_AFTER_MS = 30_000;
 70	/// Default spritesheet row for the sleep pose. Row 5 ("Failed") is unused by any
 71	/// mood in STATE_ROW, so it's free. Override with localStorage `ap_bind_sleep`.
 72	export const SLEEP_ROW_DEFAULT = 5;
 73	
 74	export const VALID_MODES: RoamMode[] = ["stay", "wander", "cursor", "climb"];
 75	
 76	/// Per-window override key. Each pet window (main, project, extra) can have
 77	/// its own roam mode / size, stored under `ap_win_<label>_<key>`. Falls back
 78	/// to the global key if the per-window override is absent.
 79	// Cache the label once at module load: getCurrentWindow() allocates a new
 80	// WebviewWindow each call, and loadConfig() runs every 30ms tick.
 81	const WIN_LABEL: string = (() => {
 82	  try {
 83	    return getCurrentWindow().label;
 84	  } catch {
 85	    return "";
 86	  }
 87	})();
 88	
 89	function winOverride(key: string): string | null {
 90	  if (!WIN_LABEL) return null;
 91	  return localStorage.getItem(`ap_win_${WIN_LABEL}_${key}`);
 92	}
 93	
 94	// Module-level cache: loadConfig() runs every 30ms tick; reading three keys
 95	// + parseInt ~100 times/sec is pure waste. Invalidated by `storage` events
 96	// (cross-window writes from Settings) and by invalidateRoamConfig() for
 97	// same-window writes.
 98	let cfgCache: Config | null = null;
 99	let cfgRaw = "";
100	
101	function snapshotRoamRaw(): string {
102	  return `${localStorage.getItem(ROAM_KEY)}|${winOverride(ROAM_MODE_KEY) ?? ""}|${localStorage.getItem(ROAM_MODE_KEY)}|${localStorage.getItem(ROAM_SPEED_KEY)}`;
103	}
104	
105	export function invalidateRoamConfig(): void {
106	  cfgCache = null;
107	  cfgRaw = "";
108	}
109	
110	let configSource: ConfigSource | null = null;
111	
112	export function setRoamConfigSource(source: ConfigSource | null): void {
113	  configSource = source;
114	  invalidateRoamConfig();
115	}
116	
117	function normalizeConfig(raw: Config): Config {
118	  const wanderPause = normalizeWanderPauseRange(raw.wanderPauseMinMs, raw.wanderPauseMaxMs);
119	  return {
120	    enabled: raw.enabled,
121	    mode: VALID_MODES.includes(raw.mode) ? raw.mode : "wander",
122	    speed: Math.max(1, Math.min(10, Math.round(raw.speed))),
123	    wanderPauseMinMs: wanderPause.minMs,
124	    wanderPauseMaxMs: wanderPause.maxMs,
125	  };
126	}
127	
128	export function loadConfig(): Config {
129	  if (configSource) return normalizeConfig(configSource());
130	  // Per-window roam mode override wins over the global setting for legacy
131	  // windows. Desktop instances inject their own config above instead.
132	  const raw = snapshotRoamRaw();
133	  if (cfgCache && raw === cfgRaw) return cfgCache;
134	  cfgRaw = raw;
135	  const stored = (winOverride(ROAM_MODE_KEY) || localStorage.getItem(ROAM_MODE_KEY)) as RoamMode | null;
136	  const mode: RoamMode = stored && VALID_MODES.includes(stored) ? stored : "wander";
137	  cfgCache = {
138	    enabled: localStorage.getItem(ROAM_KEY) !== "0",
139	    mode,
140	    speed: Math.max(1, Math.min(10, parseInt(localStorage.getItem(ROAM_SPEED_KEY) || "5", 10))),
141	    wanderPauseMinMs: DEFAULT_WANDER_PAUSE_MIN_MS,
142	    wanderPauseMaxMs: DEFAULT_WANDER_PAUSE_MAX_MS,
143	  };
144	  return cfgCache;
145	}
146	
147	if (typeof window !== "undefined") {
148	  window.addEventListener("storage", (e) => {
149	    if (!e.key || e.key === ROAM_KEY || e.key === ROAM_MODE_KEY || e.key === ROAM_SPEED_KEY ||
150	        e.key.startsWith("ap_win_")) {
151	      invalidateRoamConfig();
152	    }
153	  });
154	}
155	
156	export function clampToBounds(pos: Point, bounds: Rect): Point {
157	  return {
158	    x: Math.max(bounds.left, Math.min(bounds.right - WIN_W, pos.x)),
159	    y: Math.max(bounds.top, Math.min(bounds.bottom - WIN_H, pos.y)),
160	  };
161	}
162	
163	export function pxPerSec(speed: number): number {
164	  return 40 + speed * 45;
165	}
166	
167	export function sleep(ms: number): Promise<void> {
168	  return new Promise((r) => setTimeout(r, ms));
169	}

