168	    }
169	    if dragging && app.get_webview_window(&label).is_none() {
170	        return Err("pet window is unavailable".into());
171	    }
172	    let Some(state) = app.try_state::<Mutex<ActivePetDragSet>>() else {
173	        return Err("pet drag state is unavailable".into());
174	    };
175	    let mut active_drags = state.lock().map_err(|_| "pet drag state is unavailable")?;
176	    if dragging {
177	        active_drags.insert(label);
178	    } else {
179	        active_drags.remove(&label);
180	    }
181	    Ok(())
182	}
183	
184	/// Persist a pet's current physical position immediately after a user drag.
185	/// The periodic background save remains a safety net for programmatic motion.
186	#[tauri::command]
187	fn persist_pet_position(app: tauri::AppHandle, label: String) -> Result<(), String> {
188	    let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else {
189	        return Err("invalid pet window label".into());
190	    };
191	    if !valid_pet_id(id) {
192	        return Err("invalid pet id".into());
193	    }
194	    let Some(window) = app.get_webview_window(&label) else {
195	        return Err("pet window is unavailable".into());
196	    };
197	    let position = window.outer_position().map_err(|error| error.to_string())?;
198	    let snapshot = {
199	        let Some(state) = app.try_state::<Mutex<PetPositionMap>>() else {
200	            return Err("pet position state is unavailable".into());
201	        };
202	        let mut positions = state.lock().map_err(|_| "pet position state is unavailable")?;
203	        positions.insert(id.to_owned(), (position.x, position.y));
204	        positions.clone()
205	    };
206	    write_pet_positions(&snapshot);
207	    Ok(())
208	}
209	
210	fn lang_file() -> Option<std::path::PathBuf> {
675	            // outside its opaque rectangle and persist every instance position.
676	            let handle = app.handle().clone();
677	            std::thread::spawn(move || {
678	                let mut last_ignore: std::collections::HashMap<String, bool> = std::collections::HashMap::new();
679	                let mut flip_logs: u32 = 0;
680	                let mut last_saved = read_pet_positions();
681	                let mut tick: u32 = 0;
682	                loop {
683	                    // 60ms (≈16Hz): click-through detection doesn't need 33Hz
684	                    // polling. The cursor rarely traverses a pet's opaque rect
685	                    // in <60ms, and halving the tick rate halves the Win32
686	                    // GetCursorPos + GetWindowRect calls per second.
687	                    std::thread::sleep(Duration::from_millis(60));
688	
689	                    // Snapshot all pet windows once per tick so spawns/closes
690	                    // during the loop don't corrupt the iterator.
691	                    let wins: Vec<(String, tauri::WebviewWindow)> = handle
692	                        .webview_windows()
693	                        .into_iter()
694	                        .filter(|(label, _)| is_pet_window(label))
695	                        .collect();
696	                    // Classify visibility once per window. Hidden overlays do
697	                    // no work; an unknown state stays interactive until a later
698	                    // poll can classify it safely.
699	                    let mut visible_wins = Vec::new();
700	                    let mut unknown_visibility_wins = Vec::new();
701	                    for window in &wins {
702	                        match window.1.is_visible() {
703	                            Ok(true) => visible_wins.push(window),
704	                            Ok(false) => {}
705	                            Err(_) => unknown_visibility_wins.push(window),
706	                        }
707	                    }
708	                    for (label, win) in &unknown_visibility_wins {
709	                        apply_ignore_state(&mut last_ignore, label, false, |ignore| {
710	                            win.set_ignore_cursor_events(ignore)
711	                        });
712	                    }
713	                    let cur = if visible_wins.is_empty() {
714	                        None
715	                    } else {
716	                        handle.cursor_position().ok()
717	                    };
718	
719	                    // Snapshot all hit rects in ONE lock acquisition (instead of
720	                    // N locks per tick). The clone is ~12 entries × 32 bytes.
721	                    let rects: HitRectMap = handle
722	                        .try_state::<Mutex<HitRectMap>>()
723	                        .and_then(|s| s.lock().ok().map(|m| m.clone()))
724	                        .unwrap_or_default();
725	                    let active_drags: ActivePetDragSet = handle
726	                        .try_state::<Mutex<ActivePetDragSet>>()
727	                        .and_then(|s| s.lock().ok().map(|m| m.clone()))
728	                        .unwrap_or_default();
729	
730	                    for (label, win) in &visible_wins {
731	                        let Ok(wp) = win.outer_position() else { continue };
732	                        // Fail-safe: no rect yet (webview still booting) or
733	                        // cursor unreadable → keep INTERACTIVE.
734	                        let inside = match &cur {
735	                            Some(cur) => match rects.get(label) {
736	                                Some(r) if r.w > 0.0 => {
737	                                    let rx = cur.x - wp.x as f64;
738	                                    let ry = cur.y - wp.y as f64;
739	                                    rx >= r.x && rx <= r.x + r.w && ry >= r.y && ry <= r.y + r.h
740	                                }
741	                                _ => true, // no rect yet → stay interactive
742	                            },
743	                            None => true,
744	                        };
745	                        // An active pointer drag holds an explicit interaction
746	                        // lease so an async window move cannot make this overlay
747	                        // click-through before Pointer Capture receives its end.
748	                        let ignore = should_ignore_cursor_events(active_drags.contains(label), inside);
749	                        if apply_ignore_state(&mut last_ignore, label, ignore, |ignore| {
750	                            win.set_ignore_cursor_events(ignore)
751	                        }) {
752	                            if flip_logs < 60 {
753	                                flip_logs += 1;
754	                                let cur_str = cur.as_ref().map_or("err".to_string(), |c| format!("({:.0},{:.0})", c.x, c.y));
755	                                dlog(&format!(
756	                                    "hit flip: label={label} ignore={ignore} cur={cur_str} win=({},{})",
757	                                    wp.x, wp.y
758	                                ));
759	                            }
760	                        }
761	                    }
762	
763	                    // Prune closed windows and persist every instance position,
764	                    // both throttled to roughly once per second.
765	                    tick = tick.wrapping_add(1);
766	                    if tick % 17 == 0 {
767	                        let active: std::collections::HashSet<&String> =
768	                            wins.iter().map(|(label, _)| label).collect();
769	                        if let Some(state) = handle.try_state::<Mutex<HitRectMap>>() {
770	                            if let Ok(mut rects) = state.lock() {
771	                                rects.retain(|label, _| active.contains(label));
772	                            }
773	                        }
774	                        last_ignore.retain(|label, _| active.contains(label));
775	                        if let Some(state) = handle.try_state::<Mutex<ActivePetDragSet>>() {
776	                            if let Ok(mut active_drags) = state.lock() {
777	                                active_drags.retain(|label| active.contains(label));
778	                            }
779	                        }
780	
781	                        let mut changed = false;
782	                        for (label, window) in &visible_wins {
783	                            let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else { continue };
784	                            let Ok(position) = window.outer_position() else { continue };
785	                            let next = (position.x, position.y);
786	                            if last_saved.get(id) != Some(&next) {
787	                                last_saved.insert(id.to_owned(), next);
788	                                changed = true;
789	                            }
790	                        }
791	                        if changed {
792	                            if let Some(state) = handle.try_state::<Mutex<PetPositionMap>>() {
793	                                if let Ok(mut positions) = state.lock() {
794	                                    *positions = last_saved.clone();
795	                                    write_pet_positions(&positions);
796	                                }
797	                            }
798	                        }
799	                    }
800	                }
801	            });
802	
803	            // Tray menu , the pet window is frameless, so this is how you reach
804	            // Settings or quit the app. Labels start in the saved language; the
805	            // Settings switcher re-labels them live via the `set_lang` command.

